<?php require_once '../includes/bootstrap.php';$pageTitle='Your shopping bag | Samay';$cart=$_SESSION['cart']??[];$total=0;foreach($cart as $it)$total+=(float)$it['price']*(int)$it['quantity'];require '../includes/header.php'; ?>
